"use client";

import { Reorder, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

export type DragToReorderPrimitiveProps<T extends string> = {
  values: T[];
  onReorder: (next: T[]) => void;
  renderItem: (value: T) => ReactNode;
  ariaLabel?: string;
};

export function DragToReorderPrimitive<T extends string>({ values, onReorder, renderItem, ariaLabel = "Reorder items" }: DragToReorderPrimitiveProps<T>) {
  const reduceMotion = useReducedMotion();

  return (
    <Reorder.Group axis="y" values={values} onReorder={onReorder} aria-label={ariaLabel}>
      {values.map((value) => (
        <Reorder.Item
          key={value}
          value={value}
          dragElastic={0.24}
          whileDrag={reduceMotion ? undefined : { scale: 1.03, zIndex: 1 }}
          transition={reduceMotion ? { duration: 0.12 } : { duration: 0.18, ease: [0.16, 1, 0.3, 1] }}
        >
          {renderItem(value)}
        </Reorder.Item>
      ))}
    </Reorder.Group>
  );
}
